<?php
 namespace Pterodactyl\Services\Dezerx\Allocations; use Pterodactyl\Services\Dezerx\Theme; class EggArtwork { private const KEYWORDS = [ ['paper', 'paper'], ['purpur', 'paper'], ['pufferfish', 'paper'], ['spigot', 'paper'], ['bukkit', 'paper'], ['fabric', 'fabric'], ['quilt', 'fabric'], ['neoforge', 'neoforge'], ['forge', 'forge'], ['bungeecord', 'bungeecord'], ['waterfall', 'bungeecord'], ['velocity', 'bungeecord'], ['vanilla', 'vanilla'], ['sponge', 'vanilla'], ['minecraft', 'vanilla'], ]; private const FALLBACK = '/dezerx/eggs/other.webp'; private static ?array $configured = null; public static function logo(?string $uuid, ?string $name): string { $set = self::set(); if ($uuid !== null && ($set[$uuid]['logo'] ?? '') !== '') { return $set[$uuid]['logo']; } $slug = self::slug($name); return $slug === null ? self::FALLBACK : "/dezerx/eggs/{$slug}.webp"; } public static function banner(?string $uuid, ?string $name): array { $row = $uuid !== null ? (self::set()[$uuid] ?? []) : []; $slug = self::slug($name); $theme = Theme::config(); $default = (string) ($theme['servers.defaultArt'] ?? ''); $dark = (string) ($row['image'] ?? ''); $light = (string) ($row['imageLight'] ?? ''); if ($dark === '') { $dark = $slug !== null ? "/dezerx/eggs/bg/{$slug}.webp" : ($default !== '' ? $default : '/dezerx/eggs/bg/other.webp'); } if ($light === '') { $fallback = (string) ($theme['servers.defaultArtLight'] ?? ''); $light = $slug !== null ? "/dezerx/eggs/bg/light/{$slug}.webp" : ($fallback !== '' ? $fallback : $dark); } return ['dark' => $dark, 'light' => $light]; } public static function shipped(): array { $files = glob(public_path('dezerx/eggs/*.webp')) ?: []; sort($files); return array_values(array_map( fn (string $path) => '/dezerx/eggs/' . basename($path), $files, )); } public static function slug(?string $name): ?string { if ($name === null || trim($name) === '') { return null; } $name = mb_strtolower($name); foreach (self::KEYWORDS as [$keyword, $slug]) { if (str_contains($name, $keyword)) { return $slug; } } return null; } private static function set(): array { if (self::$configured !== null) { return self::$configured; } $rows = []; foreach ((array) (Theme::config()['servers.eggArt'] ?? []) as $row) { if (is_array($row) && ($row['egg'] ?? '') !== '') { $rows[(string) $row['egg']] = $row; } } return self::$configured = $rows; } } 